'use strict';

// MODULES //

var isSignalReference = require( '@stdlib/plot/vega/base/assert/is-signal-reference' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isUndefined = require( '@stdlib/assert/is-undefined' );
var join = require( '@stdlib/array/base/join' );


// MAIN //

/**
* Synchronizes an editor configuration with a provided schema.
*
* @private
* @param {Object} conf - configuration object
* @param {Object} schema - visualization schema
* @returns {Object} mutated configuration object
*/
function config( conf, schema ) {
	var obj = schema.title;
	if ( !obj ) {
		return conf;
	}
	if ( !isSignalReference( obj.align ) ) {
		conf.align = obj.align || '';
	}
	if ( !isSignalReference( obj.anchor ) ) {
		conf.anchor = obj.anchor || 'middle';
	}
	if ( !isSignalReference( obj.angle ) ) {
		conf.angle = obj.angle || 0;
	}
	if ( !isSignalReference( obj.baseline ) ) {
		conf.baseline = obj.baseline || '';
	}
	if ( !isSignalReference( obj.color ) ) {
		conf.color = obj.color || '#000';
	}
	if ( !isSignalReference( obj.dx ) ) {
		conf.dx = obj.dx || 0;
	}
	if ( !isSignalReference( obj.dy ) ) {
		conf.dy = obj.dy || 0;
	}
	if ( !isSignalReference( obj.font ) ) {
		conf.font = obj.font || '';
	}
	if ( !isSignalReference( obj.fontSize ) ) {
		conf.fontSize = obj.fontSize || 0;
	}
	if ( !isSignalReference( obj.fontStyle ) ) {
		conf.fontStyle = obj.fontStyle || '';
	}
	if ( !isSignalReference( obj.fontWeight ) ) {
		conf.fontWeight = obj.fontWeight || '';
	}
	if ( !isSignalReference( obj.frame ) ) {
		conf.frame = obj.frame || 'bounds';
	}
	if ( !isSignalReference( obj.limit ) ) {
		conf.limit = obj.limit || 0;
	}
	if ( !isSignalReference( obj.lineHeight ) ) {
		conf.lineHeight = obj.lineHeight || 0;
	}
	if ( !isSignalReference( obj.offset ) ) {
		conf.offset = obj.offset || 0;
	}
	if ( !isSignalReference( obj.orient ) ) {
		conf.orient = obj.orient || 'top';
	}
	if ( !isSignalReference( obj.subtitle ) ) {
		if ( isUndefined( obj.subtitle ) ) {
			conf.subtitle = '';
		} else if ( isString( obj.subtitle ) ) {
			conf.subtitle = obj.subtitle;
		} else {
			conf.subtitle = join( obj.subtitle, '\n' );
		}
	}
	if ( !isSignalReference( obj.subtitleColor ) ) {
		conf.subtitleColor = obj.subtitleColor || '#000';
	}
	if ( !isSignalReference( obj.subtitleFont ) ) {
		conf.subtitleFont = obj.subtitleFont || '';
	}
	if ( !isSignalReference( obj.subtitleFontSize ) ) {
		conf.subtitleFontSize = obj.subtitleFontSize || 0;
	}
	if ( !isSignalReference( obj.subtitleFontStyle ) ) {
		conf.subtitleFontStyle = obj.subtitleFontStyle || '';
	}
	if ( !isSignalReference( obj.subtitleFontWeight ) ) {
		conf.subtitleFontWeight = obj.subtitleFontWeight || '';
	}
	if ( !isSignalReference( obj.subtitleLineHeight ) ) {
		conf.subtitleLineHeight = obj.subtitleLineHeight || 0;
	}
	if ( !isSignalReference( obj.subtitlePadding ) ) {
		conf.subtitlePadding = obj.subtitlePadding || 0;
	}
	if ( !isSignalReference( obj.text ) ) {
		if ( isString( obj.text ) ) {
			conf.text = obj.text;
		} else {
			conf.text = join( obj.text, '\n' );
		}
	}
	return conf;
}


// EXPORTS //

module.exports = config;
